using System.Collections.Generic;

namespace VikingVillages
{
	internal static partial class VikingNewsLines
	{
		/// <summary>
		/// What a viking says about the player's deeds - a boss or miniboss they killed, a trader they met, a dungeon or
		/// biome they found, an animal they tamed, a leviathan they sailed by, a monster they dropped a tree on and a sea
		/// serpent they killed - by its pool, and the sentence put after a line when the boss or biome is beyond the
		/// viking's own
		/// </summary>
		private static readonly Dictionary<string, string[]> DeedPools = new Dictionary<string, string[]>
		{
			{ "boss/Eikthyr", new[] { "Eikthyr is down? That stag has been knocking folk flat with lightning for years!", "{player}, the stag of the Meadows! Mind you make a good pickaxe from those antlers.", "They say Eikthyr's last bolt missed you by a whisker. Odin was watching, I'm sure of it.", "First the stag, then who knows? Every saga starts somewhere, {player}." } },
			{ "boss/gd_king", new[] { "You felled The Elder! The greydwarves must be weeping sap.", "{player} cut down The Elder himself? That's the biggest tree anyone has ever chopped.", "An ancient tree throwing roots at folk... I'm glad someone finally put an end to it.", "The Black Forest feels a little lighter with The Elder gone. Well done, {player}." } },
			{ "boss/Bonemass", new[] { "Bonemass! I'd have kept my distance and held my nose, but you went right in.", "{player}, you beat Bonemass? I hope you brought a good mace and plenty of poison cures.", "Bonemass is gone? The Swamp will smell a little sweeter now. Only a little.", "They say Bonemass guarded a wishbone. May it lead you to all the silver you can carry." } },
			{ "boss/Dragon", new[] { "Moder, the mother of dragons, brought down! The skalds are already arguing over the verses.", "You fought Moder on her own mountain, {player}? I still shiver just hearing about it.", "Ice breath and wings like sails, and you beat her anyway. Odin must be proud.", "Moder is gone! I can't imagine how you even got those eggs up to her altar." } },
			{ "boss/GoblinKing", new[] { "Yagluth is dead? The fulings won't know what to do with themselves now.", "{player}, you beat the king of the fulings! I hear even his bones were bigger than our longhouse.", "The Plains burned with Yagluth's fire, and still you stood. That's a saga for the long winter nights.", "Raise a horn of mead for {player}, everyone - Yagluth has fallen!" } },
			{ "boss/SeekerQueen", new[] { "You went down into the Queen's hive in the mist and came back out? Incredible.", "{player} killed the Queen! The seekers will be scuttling about with no one to answer to.", "All those legs and pincers, and you beat her. I'd never have even found the way in.", "The Queen is dead. The Dvergr must be lighting a lantern in your honor tonight." } },
			{ "boss/Fader", new[] { "Fader, the fire dragon of the Ashlands, defeated! Not even Valhalla has seen a fight like that.", "{player}, you rang Fader's bells and lived to tell of it? I'd have run the other way.", "They say the very ground burned under Fader. I hope your boots came back in one piece.", "Fader has fallen. The skalds will need a whole new song for that one." } },
			{ "boss/FrozenKing", new[] { "Kall Fimbulbringer, the Shackled One, is no more? {player}, you've done what the sagas only dreamed of.", "You went to the far frozen north and came back a victor. Odin himself must be on his feet.", "Fimbulbringer! Even the name makes my breath freeze. And you beat the Shackled One!", "None of us could even stand in that cold, let alone fight the Shackled One. Well done, {player}." } },
			{ "miniboss/Brenna", new[] { "Brenna is laid to rest at last? I always heard she burned hot, for a skeleton.", "{player}, you went into Brenna's tomb and won? Hildir will be glad to have her chest back.", "A skeleton that throws fire! I'd have run, and kept running. You're braver than me.", "So Brenna's tomb is quiet now. The forest has one less terror in it." } },
			{ "miniboss/Geirrhafa", new[] { "Geirrhafa beaten in that frost cave? It's cold enough up there without a cultist casting ice.", "{player}, you beat Geirrhafa? Fenrings and frost magic both - you must have nerves of iron.", "Hildir sent you after Geirrhafa and you came back with the chest? She picks her heroes well.", "The howling in the mountain caves must be a little quieter now, thanks to you." } },
			{ "miniboss/ZilThungr", new[] { "Zil and Thungr, both at once? Two fuling brothers, and you sent them both packing.", "{player}, they say you beat Zil and Thungr in their tower. The other fulings must be fuming.", "One fuling chief is trouble enough. Two brothers fighting together... and you won anyway!", "Zil and Thungr gone! Hildir will be glad to see that last chest of hers again." } },
			{ "trader/Haldor", new[] { "You found Haldor! Bring him plenty of coins - he never gives anything away.", "{player}, you met the trader in the Black Forest? Don't let him talk you into buying everything.", "Save your amber and rubies for Haldor. He pays well for pretty things.", "Haldor's a hard bargainer, but a fair one. A good friend to have out in the woods." } },
			{ "trader/Hildir", new[] { "You met Hildir! Now you can finally dress like someone with taste, {player}.", "Haldor's sister, Hildir? She's lost a few chests, I hear. Help her if you can.", "Hildir sells the finest clothes in all the land. I'd trade my best axe for one of her hats.", "{player}, Hildir's dyes and finery are just what this village needs. Bring back something nice!" } },
			{ "trader/BogWitch", new[] { "You found the Bog Witch? Rather you than me. Did she offer you anything to eat?", "{player}, the Bog Witch's spices make the best feasts. Bring some back for our cook pot.", "A witch living out in the Swamp, selling strange things... I'd count my fingers after a visit.", "They say the Bog Witch knows more about cooking than all of us put together. Learn what you can!" } },
			{ "dungeon/BurialChambers", new[] { "You went down into a burial chamber? Skeletons and ghosts... I'd keep a torch in each hand.", "{player}, the crypts of the Black Forest! Did you bring back any surtling cores?", "The crypts are dark and full of bones that bite. Glad to see you made it back out.", "Your first burial chamber! I hear the ghosts in there wail enough to curdle mead." } },
			{ "dungeon/TrollCave", new[] { "You walked into a troll's cave? On purpose? You're braver than any of us, {player}.", "A troll cave! I hope you remembered to duck - trolls swing their clubs wide.", "Trolls love their caves. They don't love visitors. How did you get out with your head?", "{player}, they say a troll cave smells worse than the Swamp. Is it true?" } },
			{ "dungeon/FrostCave", new[] { "A frost cave, deep in the mountains! Fenrings, cultists and bats, all in one place.", "{player}, you went into a frost cave? Pack a frost resistance mead next time, if you didn't.", "The caves under the mountains howl at night. Now you know why, I suppose.", "They say the treasure in the frost caves is worth the frostbite. Was it?" } },
			{ "biome/BlackForest", new[] { "The Black Forest! Watch for greydwarves - they throw stones and come in packs.", "{player}, there's copper and tin in the Black Forest. Bronze is waiting for you!", "Trolls roam the Black Forest. If the trees start falling, run first and ask later.", "The Black Forest is dark even at noon. Keep a torch handy and your shield closer." } },
			{ "biome/Swamp", new[] { "The Swamp! Mind the leeches in the water and the draugr on the mounds.", "{player}, there's iron in the sunken crypts of the Swamp. You'll need a Swamp key to get in.", "It always rains in the Swamp. Your boots will never be dry again.", "Keep a poison resistance mead on your belt in the Swamp. Those blobs aren't just for show." } },
			{ "biome/Mountain", new[] { "The Mountains! Wear something warm or drink a frost resistance mead, or you'll freeze solid.", "{player}, there's silver in the Mountains. You'll need a wishbone to find it.", "Wolves hunt in packs up in the Mountains, and drakes spit ice. Keep your shield up.", "Stone golems walk the Mountain peaks. If a rock gets up and moves, don't stay to look." } },
			{ "biome/Plains", new[] { "The Plains look peaceful, but the deathsquitos will find you before you see them.", "Fulings build their villages out on the Plains, and they don't like visitors.", "There's barley and flax in the Plains, {player}. Bread and linen, at last!", "Lox graze out on the Plains. Big as a house and twice as grumpy - give them room." } },
			{ "biome/Mistlands", new[] { "The Mistlands! You won't see your own hand in that fog. Bring a wisp light if you can.", "{player}, seekers and ticks crawl all through the Mistlands. Don't let anything bite your neck.", "The Dvergr have outposts in the Mistlands. Be polite, and don't help yourself to their chests.", "Gjall drift over the Mistlands like great angry clouds. Look up now and then." } },
			{ "biome/AshLands", new[] { "The Ashlands! They say even the sea there burns your boat. Keep well clear of the lava.", "{player}, the ground itself is burning in the Ashlands. Fire resistance is a must.", "Charred warriors and fallen Valkyries in the Ashlands... it sounds like the end of the world.", "They say flametal lies under the ash. Only the boldest come back with it." } },
			{ "biome/DeepNorth", new[] { "The Deep North! I didn't think anyone could survive the cold that far up.", "{player}, they say the ice up north never melts. Bundle up, and then bundle up again.", "Nobody from here has ever seen the Deep North. Tell us what's up there, when you can.", "The Deep North, at the very edge of the world. Even the skalds don't know any songs about it." } },
			{ "biome/Ocean", new[] { "The open sea! Watch for serpents in a storm - they love to snap at small boats.", "{player}, far out at sea there are leviathans as big as islands. Don't try building a house on one.", "A raft is fine for a pond, but for the open sea you want a longship under you.", "Even a karve feels like a dragon under you once the sail fills. Mind the rudder!", "A Viking without a ship is just a farmer with an axe. Now you're the real thing!", "Wind at your back and salt in your beard - now you're a true Viking, {player}!" } },
			{ "tame/Boar", new[] { "You tamed a boar! Feed it well and you'll have piglets running everywhere before long.", "{player}, a tame boar? Mind it doesn't eat all the village's carrots.", "A boar at your side, grunting along happily. It's the start of a fine farm.", "Taming a boar takes patience and berries. You clearly have plenty of both." } },
			{ "tame/Wolf", new[] { "A tame wolf! Now you have a friend who'll follow you anywhere and bite whatever you point at.", "{player}, you tamed a wolf from the Mountains? I'd have been too busy running.", "Feed your wolf plenty of meat and it'll guard your home better than any fence.", "Keep two wolves and you'll have cubs soon enough. A pack of your own!" } },
			{ "tame/Lox", new[] { "You tamed a lox! One of those could carry half the village on its back.", "{player}, a lox! Get a saddle on it and ride across the Plains like a jarl.", "Lox eat a mountain of barley and cloudberries. I hope your fields are big.", "Taming a lox without getting stepped on... that's a feat in itself!" } },
			{ "tame/Asksvin", new[] { "You tamed an Asksvin! Riding a lizard through the Ashlands - now that's a sight.", "{player}, a tame Asksvin? I didn't think anything from the Ashlands could be friendly.", "An Asksvin is fast on its feet, they say. Hold on tight when you ride it.", "Taming one of those lizards from the burning lands... you have the patience of the gods." } },
			{ "tame/*", new[] { "You tamed a {creature}? I didn't even know that was possible!", "{player} has a tame {creature} now! What next, a pet troll?", "A {creature} that follows you about like a dog. Odin's beard, I've seen it all now.", "Look after your {creature} well, and it'll look after you." } },
			{ "leviathan", new[] { "You sailed right past a leviathan? I hear they're as big as islands, and twice as old.", "{player}, a leviathan! Did you try mining its shell before it dove?", "A leviathan close enough to touch... the sea has more wonders than any of us will ever see.", "Hit a leviathan and down it goes, taking you with it if you're standing on it. Careful out there!" } },
			{ "tree/monster", new[] { "You dropped a tree on a {creature}? Ha! That's one way to clear a forest.", "{player} squashed a {creature} with a falling tree! Now that's clever woodcutting.", "Timber! I'd have loved to see the look on that {creature}'s face.", "A {creature} flattened by a tree. The skalds will laugh about that one for years." } },
			{ "tree/sea", new[] { "A tree... on a {creature}... out at sea? Where did you even find a tree out there?", "{player}, they say you killed a {creature} at sea with a falling tree. How is that even possible?", "A {creature}, out in the waves, felled by a tree! Odin himself must be scratching his head.", "I've heard plenty of tales, but a {creature} killed by a tree in the middle of the sea? That beats them all." } },
			{ "tree/boss", new[] { "You killed {creature} by dropping a tree on it? The other Forsaken must fear woodcutters now!", "{player} felled {creature} with a falling tree! That's a saga nobody will believe.", "{creature}, brought down by a tree? Not a sword, not an arrow - a tree! I love it.", "The skalds will sing of how {creature} met its end under a falling trunk. Legendary!" } },
			{ "serpent/Serpent", new[] { "You killed a sea serpent! Its scales make a fine shield, you know.", "{player}, a sea serpent! Those monsters have sunk more boats than I can count.", "A serpent, slain at sea! I hope you brought back the meat - serpent stew is the best there is.", "Fighting a serpent from a rocking boat in a storm... you're a true Viking, through and through." } },
			{ "serpent/BonemawSerpent", new[] { "A Bonemaw! The serpent of the burning sea, and you brought it down!", "{player}, you killed a Bonemaw in the Ashlands' waters? Did your boat survive the heat?", "A serpent of bone and fury, and you beat it. I'll never complain about our river again.", "They say a Bonemaw's teeth are as sharp as spears. Did you keep one as a trophy?" } },
			{ "impressed/boss", new[] { "We'd never stand a chance against that here!", "Nobody in this village could have done that.", "I'd have dropped my axe and run!", "That's far beyond anything we've ever faced.", "Even our bravest would turn pale at that.", "We can only dream of a fight like that." } },
			{ "impressed/biome", new[] { "That's far beyond our lands!", "None of us have ever traveled that far.", "I can't even imagine going that far from home.", "We've only heard stories of places like that.", "That's a long way from our little corner of the world.", "Our maps don't even go that far!" } }
		};
	}
}
